#[cfg(test)]mod tests {
use super::*;use crate::auto_tool::{AutoTool,ToolSelector};
fn common()->CommonSettings{CommonSettings{enabled:true,hidden:false,key_bind:json!({"key":"key.keyboard.unknown","modifiers":[]})}}
fn apply(tree:&Value,state:&mut AutoTool)->Vec<ConfigError>{let mut p=SettingsPatch::default();auto::parse_auto_tool(&mut p,&nodes(tree,"AutoTool","AutoTool").unwrap());let mut errors=p.issues;for change in p.changes{let SettingChange::AutoTool(change)=change;if let Err(e)=change.apply(state,&["minecraft:air".into(),"minecraft:stone".into(),"minecraft:ender_chest".into(),"minecraft:glowstone".into(),"minecraft:sea_lantern".into(),"minecraft:turtle_egg".into()]){errors.push(e);}}errors}
#[test]fn actual_full_config_roundtrip_and_hidden_millisecond_marker(){let mut state={let mut m=AutoTool::default();m.tool_selector=ToolSelector::Static;m.slot=7;m.consider_inventory=true;m.ignore_durability=true;m.switch_delay=3;m.require_near_bed=true;m};state.constraints.requirements=31;for format in [JsonFormat::Interop,JsonFormat::File]{let tree=auto::serialize_auto_tool(&state,&common(),format,&str::to_owned).unwrap();let text=tree.to_string();assert_eq!(text.contains("MillisecondDelays"),format==JsonFormat::File);assert!(text.contains("ToolSelector"));assert!(text.contains("ConsiderInventory"));let mut restored=AutoTool::default();assert!(apply(&tree,&mut restored).is_empty());assert_eq!(restored,state);let names:Vec<_>=tree["value"].as_array().unwrap().iter().map(|v|v["name"].as_str().unwrap()).collect();let suffix=&names[if format==JsonFormat::Interop{2}else{3}..];assert_eq!(suffix,["ToolSelector","Filter","Blocks","SilkTouchHandler","SwapBackDelay","SwitchDelay","RequireSneaking","NotDuringCombat","RequireNearBed"]);}}
fn constraints_tree(values:Value,typed:bool)->Value{let mut group=json!({"name":"Constraints","value":values});if typed{group["valueType"]=json!("CONFIGURABLE");}json!({"name":"AutoTool","value":[{"name":"ToolSelector","active":"Dynamic","choices":{"Dynamic":{"name":"Dynamic","value":[{"name":"ConsiderInventory","value":[group]}]},"Static":{"name":"Static","value":[]}}}]})}
#[test]fn legacy_tick_delay_migration_and_marker_compatibility(){for (typed,marker,expected)in [(false,false,[100,200]),(true,false,[2,4]),(false,true,[2,4])]{let mut v=vec![json!({"name":"StartDelay","value":{"from":2,"to":4}})];if marker{v.push(json!({"name":"MillisecondDelays","value":false}));}let tree=constraints_tree(json!(v),typed);let mut state=AutoTool::default();assert!(apply(&tree,&mut state).is_empty());assert_eq!(state.constraints.start_delay,expected);if marker{assert!(!state.constraints.millisecond_delays);}}let tree=constraints_tree(json!([{"name":"StartDelay","value":3}]),false);assert_eq!(apply(&tree,&mut AutoTool::default()).len(),1);}
#[test]fn integer_overflow_ranges_alias_and_partial_multichoice_import(){let tree=constraints_tree(json!([{"name":"StartDelay","value":{"from":2147483647,"to":2147483647}}]),false);let mut state=AutoTool::default();assert!(apply(&tree,&mut state).is_empty());assert_eq!(state.constraints.start_delay,[-50,-50]);let tree=json!({"name":"AutoTool","value":[{"name":"SwapPreviousDelay","value":35}]});assert!(apply(&tree,&mut state).is_empty());assert_eq!(state.swap_back_delay,35);let tree=constraints_tree(json!([{"name":"Requires","value":["NoMovement","NOrotation",{},"NotBreaking"]}]),true);assert_eq!(apply(&tree,&mut state).len(),1);assert_eq!(state.constraints.requirements,3);let tree=constraints_tree(json!([{"name":"Requires","value":null}]),true);assert!(apply(&tree,&mut state).is_empty());assert_eq!(state.constraints.requirements,0);}
#[test]fn registry_list_uses_defaulted_air_and_identifier_sorting(){let tree=json!({"name":"AutoTool","value":[{"name":"Blocks","value":["stone","unknown:nope",17]}]});let mut state=AutoTool::default();assert!(apply(&tree,&mut state).is_empty());assert_eq!(state.blocks.iter().map(String::as_str).collect::<Vec<_>>(),["minecraft:air","minecraft:stone"]);}
}
